   273	\subsection{Orthogonalization lemma}\label{sec:orthogonalization}
   274	
   275	To show \Cref{thm:orthonormalization},
   276	we first show it for the case when~$A$ is a measurement, rather than a sub-measurement.
   277	Our proof of this case will even work in the more general setting
   278	when the strategy is not assumed to be symmetric,
   279	meaning that~$\ket{\psi}$ is not necessarily permutation-invariant and Player~$\mathrm{B}$'s measurement~$B$ may not be equal to Player~$\mathrm{A}$'s measurement.
   280	This is the content of the following lemma, whose proof we defer till later. 
   281	
   282	\begin{lemma}[Orthogonalization lemma for measurements]\label{lem:orthonormalization-main-lemma}
   283	Let $\ket{\psi}$ be a state (which is not necessarily permutation-invariant),
   284	and let $A = \{A_a\}$ and $B = \{B_a\}$ be measurements such that
   285	\begin{equation*}
   286	A_a \ot I \simeq_{\zeta} I \ot B_a
   287	\end{equation*}
   288	on state $\ket{\psi}$.
   289	Then there exists a projective sub-measurement $P = \{P_a\}$ such that
   290	\begin{equation*}
   291	A_a \otimes I \approx_{84 \zeta^{1/4}} P_a \otimes I.
   292	\end{equation*}
   293	\end{lemma}
   294	
   295	(Note that when $\ket{\psi}$ is permutation-invariant and $B = A$, the condition $A_a \ot I \simeq_{\zeta} I \ot B_a$
   296	is equivalent to~$A_a$ being $\zeta$-strongly self-consistent, by \Cref{prop:other-two-notions-of-self-consistency}.
   297	This is because~$A$ is a measurement.)
   298	
   299	
   300	
   301	We now prove \Cref{thm:orthonormalization} by reducing the general (sub-measurement) case
   302	to the case when~$A$ is a measurement.
   303	
   304	\begin{proof}[Proof of \Cref{thm:orthonormalization} assuming \Cref{lem:orthonormalization-main-lemma}]
   305	Let $A = \{A_a\}$ be a sub-measurement with outcomes $a \in \calA$ whose strong self-consistency is
   306	\begin{equation*}
   307	\sum_a \bra{\psi} A_a \otimes A_a \ket{\psi} \geq \sum_a \bra{\psi} A_a \otimes I \ket{\psi} -\zeta.
   308	\end{equation*}
   309	Note that
   310	\begin{equation*}
   311	\bra{\psi} A \otimes A \ket{\psi}
   312	= \sum_{a, b} \bra{\psi} A_a \otimes A_b \ket{\psi}
   313	\geq \sum_{a} \bra{\psi} A_a \otimes A_a \ket{\psi}
   314	\geq  \bra{\psi} A \otimes I \ket{\psi} -\zeta.
   315	\end{equation*}
   316	Rearranging,
   317	\begin{align*}
   318	\bra{\psi} A \otimes (I - A)\ket{\psi}
   319	&= \bra{\psi} A \otimes I \ket{\psi} - \bra{\psi} A \otimes A \ket{\psi}\\
   320	&\leq (\bra{\psi} A \otimes A \ket{\psi} + \zeta) - \bra{\psi} A \otimes A \ket{\psi}
   321	 = \zeta.
   322	\end{align*}
   323	As a result,
   324	\begin{align*}
   325	\bra{\psi} (I-A) \otimes (I-A) \ket{\psi}
   326	&= \bra{\psi} (I-A) \otimes I \ket{\psi} - \bra{\psi} (I-A) \otimes A \ket{\psi}\\
   327	&\geq \bra{\psi} (I-A) \otimes I \ket{\psi} - \zeta.
   328	\end{align*}
   329	
   330	
   331	Let $\widehat{A}$ be the POVM measurement with outcomes in $\widehat{\calA} = \calA \cup \{\bot\}$ defined as
   332	\begin{equation*}
   333	\widehat{A}_a
   334	= \left\{\begin{array}{cl}
   335			A_a & \text{if $a \in \calA$},\\
   336			(I-A) & \text{if $a = \bot$.}
   337			\end{array}\right.
   338	\end{equation*}
   339	Then the strong self-consistency of $\widehat{A}$ is
   340	\begin{align*}
   341	\sum_{a \in \widehat{\calA}} \bra{\psi} \widehat{A}_a \otimes \widehat{A}_a \ket{\psi}
   342	& = \sum_{a \in \calA} \bra{\psi} A_a \otimes A_a \ket{\psi}
   343		+ \bra{\psi} \widehat{A}_{\bot} \otimes \widehat{A}_{\bot} \ket{\psi}\\
   344	& \geq \Big(\sum_{a \in \calA} \bra{\psi} A_a \otimes I \ket{\psi} - \zeta\Big)
   345		+ \bra{\psi} (I-A) \otimes (I-A) \ket{\psi}\\
   346	& \geq \Big( \bra{\psi} A \otimes I \ket{\psi} - \zeta\Big)
   347		+ \Big(\bra{\psi} (I-A) \otimes I \ket{\psi} - \zeta\Big)\\
   348	& = 1 - 2\zeta.
   349	\end{align*}
   350	Because $\widehat{A}$ is a measurement,
   351	\Cref{prop:other-two-notions-of-self-consistency} states that this is equivalent to
   352	\begin{equation*}
   353	\widehat{A}_a \ot I \simeq_{2\zeta} I \ot \widehat{A}_a.
   354	\end{equation*}
   355	As a result, \Cref{lem:orthonormalization-main-lemma} implies the existence of a projective sub-measurement
   356	$\widehat{P} = \{\widehat{P}_a\}_{a \in \widehat{\calA}}$ such that 
   357	\begin{equation*}
   358	\widehat{A}_a \ot I \approx_{84\cdot(2\zeta)^{1/4}} \widehat{P}_a \ot I.
   359	\end{equation*}
   360	If we define the projective sub-measurement $P = \{P_a\}_{a \in \calA}$
   361	by $P_a = \widehat{P}_a$ for all $a \in \calA$, then
   362	\begin{equation*}
   363	\sum_{a \in \calA} \Vert (A_a - P_a) \ot I \ket{\psi} \Vert^2
   364	\leq \sum_{a \in \widehat{\calA}} \Vert (\widehat{A}_a - \widehat{P}_a) \ot I \ket{\psi} \Vert^2
   365	\leq 84 \cdot (2\zeta)^{1/4}.
   366	\end{equation*}
   367	Thus, $A_a \ot I \approx_{84 \cdot (2\zeta)^{1/4}} P_a \ot I$.
   368	We conclude the proof by noting that $84 \cdot (2\zeta)^{1/4} \leq 100 \cdot \zeta^{1/4}$
   369	because $84 \cdot (2)^{1/4} \approx 99.89\leq100$.
   370	\end{proof}
   371	
   372	Now we prove \Cref{lem:orthonormalization-main-lemma}.
   373	
   374	\begin{proof}[Proof of~\Cref{lem:orthonormalization-main-lemma}]
   375	We note that the lemma as stated is trivial when $\zeta > 1/4$.
   376	As a result, we will assume that
   377	\begin{equation}\label{eq:assumption-on-zeta}
   378	\zeta \leq 1/4.
   379	\end{equation}
   380	Let $A = \{A_a\}$ and~$B = \{B_a\}$ be POVM measurements such that
   381	\begin{equation*}
   382	A_a \ot I \simeq_{\zeta} I \ot B_a.
   383	\end{equation*}
   384	
   385	By \Cref{prop:simeq-for-measurements}, this implies that
   386	\begin{equation*}
   387	\sum_a \bra{\psi}A_a \ot B_a \ket{\psi} \geq 1 - \zeta.
   388	\end{equation*}
   389	Applying Cauchy-Schwarz, we have
   390	\begin{align*}
   391	\sum_a \bra{\psi} A_a \otimes B_a \ket{\psi}
   392	&= \sum_a \bra{\psi} (A_a \ot I) \cdot (I \ot B_a) \ket{\psi}\nonumber\\
   393	&\leq \sqrt{\sum_a \bra{\psi} (A_a)^2 \ot I \ket{\psi}} \cdot \sqrt{\sum_a \bra{\psi} I \ot (B_a)^2 \ket{\psi}}\nonumber\\
   394	& \leq \sqrt{\sum_a \bra{\psi} (A_a)^2 \ot I \ket{\psi}} \cdot 1.
   395	\end{align*}
   396	Taking the square of both sides,
   397	\begin{equation*}
   398	\sum_a \bra{\psi} (A_a)^2 \ot I \ket{\psi} \geq \Big(\sum_a \bra{\psi} A_a \otimes B_a \ket{\psi}\Big)^2 \geq (1-\zeta)^2
   399	\geq 1 - 2\zeta
   400	= \sum_a \bra{\psi} A_a \ot I \ket{\psi} - 2\zeta. \tag{because~$A$ is a measurement}
   401	\end{equation*}
   402	
   403	Rearranging,
   404	\begin{equation}\label{eq:A-looks-projective}
   405	\sum_a \bra{\psi} (A_a - (A_a)^2) \otimes I \ket{\psi}
   406	\leq 2\zeta.
   407	\end{equation}
   408	This is all we need the~$B$ measurement for; henceforth, we will derive consequences of~\Cref{eq:A-looks-projective}.
   409	
   410	In our next lemma, we convert each~$A_a$ to a projective matrix~$R_a$
   411	by rounding each of $A_a$'s large eigenvalues to~$1$
   412	and small eigenvalues to~$0$.
   413	
   414	\begin{lemma}[Rounding to projectors]\label{lem:projective-non-measurement}
   415	There exists a set of projective matrices $\{R_a\}$ such that
   416	\begin{equation*}
   417	A_a \ot I \approx_{2\sqrt{\zeta}} R_a \ot I.
   418	\end{equation*}
   419	and
   420	\begin{equation*}
   421	R:= \sum_a R_a \leq (1+2\sqrt{\zeta}) \cdot I.
   422	\end{equation*}
   423	\end{lemma}
   424	\begin{proof}
   425	For each~$a$, we write the eigendecomposition of $A_a$ as follows: 
   426	\begin{equation*}
   427	A_a = \sum_i \lambda_{a, i} \cdot\ket{u_{a, i}} \bra{u_{a, i}}.
   428	\end{equation*}
   429	Let
   430	\begin{equation}\label{eq:bound-on-delta}
   431	0 < \delta \leq 1/2
   432	\end{equation}
   433	be a number to be decided later.
   434	Let $\mathsf{trunc}_\delta:[0, 1] \rightarrow \{0, 1\}$ be the truncation function defined as
   435	\begin{equation*}
   436	\mathsf{trunc}_\delta(x) =
   437	\left\{\begin{array}{rl}
   438		1 & \text{if } x \geq 1- \delta,\\
   439		0 & \text{otherwise.}
   440		\end{array}\right.
   441	\end{equation*}
   442	Then for each~$a$ we define the matrix $R_a$
   443	\begin{equation*}
   444	R_a = \mathsf{trunc}_\delta(A_a) = \sum_i \mathsf{trunc}_\delta(\lambda_{a, i}) \cdot \ket{u_{a, i}} \bra{u_{a, i}}.
   445	\end{equation*}
   446	To analyze this, we will require the following technical lemma.
   447	\begin{lemma}\label{lem:trunc-inequality}
   448	For any $x \in [0, 1]$,
   449	\begin{equation*}
   450	(x - \mathsf{trunc}_\delta(x))^2 \leq \frac{1}{\delta} \cdot (x - x^2).
   451	\end{equation*}
   452	\end{lemma}
   453	\begin{proof}
   454	This is proved by case analysis.
   455	First, suppose that $x \geq 1 - \delta$.
   456	This implies that $\mathsf{trunc}_\delta(x) = 1$.
   457	In addition, because $\delta \leq 1/2$ by \Cref{eq:bound-on-delta},
   458	$
   459	x \geq 1 - \delta \geq 1/2 \geq \delta.
   460	$
   461	Thus,
   462	\begin{align*}
   463	(x - \mathsf{trunc}_\delta(x))^2
   464	& = (1-x)^2\\
   465	 &\leq (1-x)\\
   466	&\leq (1-x) \cdot \frac{x}{\delta} \tag{because $x \geq \delta$}\\
   467	&= \frac{1}{\delta} \cdot (x - x^2).
   468	\end{align*}
   469	Next, suppose that $x < 1 -\delta$.
   470	This implies that $\mathsf{trunc}_\delta(x) = 0$.
   471	Thus,
   472	\begin{align*}
   473	(x - \mathsf{trunc}_\delta(x))^2
   474	& = x^2\\
   475	 &\leq x\\
   476	&\leq x \cdot \frac{(1-x)}{\delta} \tag{because $x \leq 1- \delta$}\\
   477	&= \frac{1}{\delta} \cdot (x - x^2).
   478	\end{align*}
   479	This concludes the proof.
   480	\end{proof}
   481	
   482	As a result, for each~$a$, \Cref{lem:trunc-inequality} implies that
   483	\begin{equation*}
   484	(A_a - R_a)^2 = (A_a - \mathsf{trunc}_\delta(A_a))^2 \leq \frac{1}{\delta} \cdot (A_a - (A_a)^2).
   485	\end{equation*}
   486	Thus,
   487	\begin{align*}
   488	\sum_a \Vert (A_a - R_a) \ot I \ket{\psi}\Vert^2
   489	= \sum_a \bra{\psi} (A_a - R_a)^2 \ot I\ket{\psi}
   490	&\leq \frac{1}{\delta} \cdot \sum_a \bra{\psi} (A_a - (A_a)^2) \ot I \ket{\psi}\\
   491	&\leq \frac{1}{\delta} \cdot 2\zeta. \tag{by \Cref{eq:A-looks-projective}}
   492	\end{align*}
   493	This implies that $A_a \otimes I \approx_{2\zeta/\delta} R_a \otimes I$.
   494	
   495	Next, for each $x \in [0, 1]$, it follows from the definition of $\mathsf{trunc}_\delta$ that
   496	\begin{equation*}
   497	\mathsf{trunc}_\delta(x) \leq \left(\frac{1}{1-\delta}\right) \cdot x.
   498	\end{equation*}
   499	Thus, for each~$a$
   500	\begin{equation*}
   501	R_a = \mathsf{trunc}_\delta(A_a) \leq \left(\frac{1}{1-\delta}\right) \cdot A_a.
   502	\end{equation*}
   503	Summing over all~$a$,
   504	\begin{equation*}
   505	R = \sum_a R_a \leq \left(\frac{1}{1-\delta}\right) \cdot \sum_a A_a = \left(\frac{1}{1-\delta}\right) \cdot A
   506	= \left(\frac{1}{1-\delta}\right) \cdot I,
   507	\end{equation*}
   508	because~$A$ is a measurement.
   509	We note that
   510	\begin{equation*}
   511	\frac{1}{1-\delta}
   512	= \frac{1}{1-\delta} \cdot \frac{1 + 2\delta}{1 + 2\delta}
   513	= \frac{1 + 2\delta}{1 + \delta - 2\delta^2}
   514	\leq 1 + 2\delta,
   515	\end{equation*}
   516	because
   517	\begin{equation*}
   518	1 + \delta - 2\delta^2 = 1 + \delta\cdot(1-2\delta)\geq 1
   519	\end{equation*}
   520	when $\delta \leq 1/2$,
   521	which we assumed in \Cref{eq:bound-on-delta}.
   522	Hence,
   523	\begin{equation*}
   524	R \leq (1+ 2\delta) \cdot I.
   525	\end{equation*}
   526	
   527	
